const DOC_TIPOS_BASE = { ...DOC_TIPOS };
const DOC_CATEGORIA_BASE = { ...DOC_CATEGORIA };
function sincronizarTiposDocumento(extras) {
  Object.keys(DOC_TIPOS).forEach((k) => { if (!(k in DOC_TIPOS_BASE)) { delete DOC_TIPOS[k]; delete DOC_CATEGORIA[k]; } });
  (extras || []).forEach((t) => { DOC_TIPOS[t.id] = t.nome; DOC_CATEGORIA[t.id] = t.categoria; });
}

