function fmtCPF(v) {
  const c = so(v).slice(0, 11);
  if (c.length <= 3) return c;
  if (c.length <= 6) return `${c.slice(0, 3)}.${c.slice(3)}`;
  if (c.length <= 9) return `${c.slice(0, 3)}.${c.slice(3, 6)}.${c.slice(6)}`;
  return `${c.slice(0, 3)}.${c.slice(3, 6)}.${c.slice(6, 9)}-${c.slice(9)}`;
}
const mascararCPF = (v) => { const c = so(v); if (!c) return "Não informado"; if (c.length !== 11) return "Incompleto"; return `***.${c.slice(3, 6)}.***-${c.slice(9)}`; };
const fmtCEP = (v) => { const c = so(v).slice(0, 8); return c.length > 5 ? `${c.slice(0, 5)}-${c.slice(5)}` : c; };

const moeda = (n) => (n === null || n === undefined ? "não informado" : Number(n).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }));
function idade(iso) {
  if (!iso) return null;
  const n = new Date(`${iso}T12:00:00`);
  if (Number.isNaN(n.getTime())) return null;
  const h = new Date();
  let a = h.getFullYear() - n.getFullYear();
  if (h.getMonth() < n.getMonth() || (h.getMonth() === n.getMonth() && h.getDate() < n.getDate())) a--;
  return a;
}
const dataBR = (iso) => { if (!iso) return "não informada"; const [a, m, d] = iso.slice(0, 10).split("-"); return `${d}/${m}/${a}`; };
const dataHoraBR = (iso) => new Date(iso).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
const getPath = (o, path) => path.split(".").reduce((a, k) => (a == null ? undefined : a[k]), o);
function setPath(o, path, v) {
  const ks = path.split(".");
  let cur = o;
  for (let i = 0; i < ks.length - 1; i++) { if (cur[ks[i]] == null) cur[ks[i]] = {}; cur = cur[ks[i]]; }
  cur[ks[ks.length - 1]] = v;
}
function achatar(o, pre = "") {
  return Object.entries(o || {}).reduce((acc, [k, v]) => {
    const p = pre ? `${pre}.${k}` : k;
    if (v && typeof v === "object") Object.assign(acc, achatar(v, p)); else acc[p] = v;
    return acc;
  }, {});
}
const temValor = (v) => { if (v === null || v === undefined) return false; if (Array.isArray(v)) return v.some(temValor); if (typeof v === "object") return Object.values(v).some(temValor); return String(v).trim() !== ""; };
function baixarCSV(nome, linhas) {
  const csv = "\uFEFF" + linhas.map((l) => l.map((c) => `"${String(c ?? "").replace(/"/g, '""')}"`).join(";")).join("\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const a = document.createElement("a");
  a.href = url; a.download = nome; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1500);
}
async function impressaoDigital(arquivo) {
  try {
    const h = await crypto.subtle.digest("SHA-256", await arquivo.arrayBuffer());
    return [...new Uint8Array(h)].map((b) => b.toString(16).padStart(2, "0")).join("");
  } catch (e) { return ""; }
}

/* ---------------- armazenamento e imagens ---------------- */
const memoriaLocal = new Map();
const armazenamento = {
  async get(chave) {
    if(chave?.startsWith('erp-storage|'))return lerArquivoERP(chave);
    const remoto=await obterArquivo(chave);if(remoto!==undefined)return remoto;
    try { if (typeof window !== "undefined" && window.storage) { const r = await window.storage.get(chave, false); if (r && r.value !== undefined) return r.value; } } catch (e) { /* chave inexistente */ }
    return memoriaLocal.has(chave) ? memoriaLocal.get(chave) : null;
  },
  async set(chave, valor) {
    memoriaLocal.set(chave, valor);
    try { if (typeof window !== "undefined" && window.storage) await window.storage.set(chave, valor, false); } catch (e) { console.error("Falha ao salvar", chave, e); throw e; }
    await agendarArquivo(chave,valor);
  },
  async del(chave) {
    memoriaLocal.delete(chave);
    try { if (typeof window !== "undefined" && window.storage) await window.storage.delete(chave, false); } catch (e) { /* já não existia */ }
    await agendarArquivo(chave,null);
  },
};
async function comprimirImagem(arquivo, max = 1280, qualidade = 0.72) {
  const url = URL.createObjectURL(arquivo);
  try {
    const img = await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error("arquivo de imagem inválido")); i.src = url; });
    const esc = Math.min(1, max / Math.max(img.width, img.height));
    const c = document.createElement("canvas");
    c.width = Math.round(img.width * esc); c.height = Math.round(img.height * esc);
    c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
    return { dataUrl: c.toDataURL("image/jpeg", qualidade), largura: c.width, altura: c.height };
  } finally { URL.revokeObjectURL(url); }
}
const escaparHtml = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const dataExtenso = (d = new Date()) => d.toLocaleDateString("pt-BR", { day: "numeric", month: "long", year: "numeric" });
function limparHtml(html) {
  if (typeof DOMParser === "undefined") return html;
  const doc = new DOMParser().parseFromString(html, "text/html");
  doc.querySelectorAll("script,iframe,object,embed,link,meta,form,input,button").forEach((e) => e.remove());
  doc.querySelectorAll("*").forEach((el) => [...el.attributes].forEach((a) => { if (/^on/i.test(a.name) || /^\s*javascript:/i.test(a.value)) el.removeAttribute(a.name); }));
  return doc.body.innerHTML;
}

