const qtdSalarios = (teto, sm) => (teto && sm ? (teto / sm).toLocaleString("pt-BR", { maximumFractionDigits: 1 }) : null);
function sugerirModalidade(p, nucleo) {
  if (!nucleo) return { aviso: "Defina o núcleo do processo para calcular a modalidade." };
  const { teto, sm } = criterioNucleo(nucleo);
  if (!teto) return { aviso: `O ${nucleo.codigo} ainda não tem teto de renda para REURB-S. Edite o núcleo para definir.` };
  const base = { teto, sm };
  const renda = parseNum(p.social.rendaFamiliar);
  if (renda === null || p.social.possuiImovel === "") return base;
  if (p.social.possuiImovel === "nao" && renda <= teto) return { ...base, modalidade: "REURB-S", motivo: `Renda familiar de ${moeda(renda)}, dentro do teto de ${moeda(teto)} do ${nucleo.codigo}, sem outro imóvel.` };
  return { ...base, modalidade: "REURB-E", motivo: p.social.possuiImovel === "sim" ? "A família declara possuir outro imóvel." : `Renda familiar de ${moeda(renda)}, acima do teto de ${moeda(teto)} do ${nucleo.codigo}.` };
}



const contaNoTotal = (r) => !r.opcional;


// O morador só conclui etapas cujo grupo o núcleo já alcançou
function bloqueioPeloNucleo(p, nucleo) {
  if (p.etapa >= TOTAL) return null;
  const g = ETAPAS[p.etapa].grupo;
  if (g === 0) return null;
  if (!nucleo) return "Defina o núcleo do morador para seguir além do Documental.";
  if (nucleo.etapa < g) return `Aguardando o ${nucleo.codigo} concluir a etapa ${NUCLEO_ETAPAS[nucleo.etapa]?.nome || ""} do núcleo.`;
  return null;
}


function progressoNucleo(db, n, k) {
  const ativos = db.processos.filter((p) => p.nucleoId === n.id && ativo(p));
  const fim = NUCLEO_ETAPAS[k]?.fim;
  const prontos = fim === null || fim === undefined ? ativos.length : ativos.filter((p) => p.etapa >= fim).length;
  return { ativos: ativos.length, prontos };
}
function requisitosNucleo(db, n, etapaId) {
  const R = [];
  const k = NUCLEO_ETAPAS.findIndex((e) => e.id === etapaId);
  const c = n.campos || {}; const ck = n.checks || {};
  const auto = (id, label, ok, detalhe = "") => R.push({ id, label, ok: !!ok, tipo: "auto", detalhe });
  const manual = (id, label) => R.push({ id, label, ok: !!ck[id], tipo: "manual" });
  const campo = (id, label, placeholder) => R.push({ id, label, ok: preenchido(c[id]), tipo: "campo", valor: c[id] || "", placeholder });
  const escolha = (id, label) => R.push({ id, label, ok: c[id] === "sim" || c[id] === "nao", tipo: "escolha", valor: c[id] || "" });
  if (k >= 0 && k <= 3) {
    const pg = progressoNucleo(db, n, k);
    const nomes = ["Mobilização, contrato e análise documental", "Topografia", "Projeto", "Prefeitura"];
    auto("moradores", `${nomes[k]} concluído em todos os moradores ativos`, pg.ativos > 0 && pg.prontos === pg.ativos, pg.ativos ? `${pg.prontos} de ${pg.ativos} moradores ativos prontos. Inativos, cancelados e banidos não contam.` : "Nenhum morador ativo no núcleo");
  }
  switch (etapaId) {
    case "documental":
      auto("teto", "Teto de renda para REURB-S definido", !!criterioNucleo(n).teto, "Defina no cadastro do núcleo");
      break;
    case "projeto":
      campo("artPrf", "ART do PRF", "Número da ART");
      escolha("estudoAmbiental", "Teve estudo ambiental?");
      if (c.estudoAmbiental === "sim") campo("artAmbiental", "ART do estudo ambiental", "Número da ART ambiental");
      escolha("estudoRisco", "Teve estudo de risco?");
      manual("termos", "Termos de compromisso elaborados");
      break;
    case "prefeitura":
      campo("protocoloPrefeitura", "Protocolo do projeto na prefeitura", "Número do protocolo");
      manual("aprovacao", "Projeto aprovado pela prefeitura");
      break;
    case "crf":
      manual("crfEmitida", "CRF emitida pela prefeitura");
      campo("prenotacao", "Prenotação da CRF no cartório", "Número da prenotação");
      manual("crfRegistrada", "CRF registrada no cartório");
      manual("matriculas", "Matrículas das unidades abertas");
      manual("titulos", "Títulos entregues aos beneficiários");
      break;
    default:
  }
  return R;
}
const pendenciasNucleo = (db, n) => (n.etapa >= TOTAL_NUCLEO ? [] : requisitosNucleo(db, n, NUCLEO_ETAPAS[n.etapa].id).filter((r) => !r.ok));

function alertasDados(p, ctx) {
  const a = [];
  const r = p.requerente;
  if (ehPJ(r)) {
    if (r.cnpj && !cnpjValido(r.cnpj)) a.push("CNPJ do requerente inválido");
    if (!r.representante) a.push("Pessoa jurídica sem representante legal informado");
  } else {
    if (r.cpf && !cpfValido(r.cpf)) a.push("CPF do requerente inválido");
    if (p.conjuge.cpf && !cpfValido(p.conjuge.cpf)) a.push("CPF do cônjuge inválido");
    if (!r.estadoCivil && r.dataUniao) a.push("Data da união preenchida, mas estado civil não informado");
    if (COM_CONJUGE.includes(r.estadoCivil) && !p.conjuge.nome) a.push(`Estado civil "${r.estadoCivil}" sem cônjuge cadastrado`);
    if (p.conjuge.nome && r.estadoCivil && !COM_CONJUGE.includes(r.estadoCivil)) a.push("Cônjuge cadastrado, mas o estado civil não indica união");
    const i = idade(r.nascimento);
    if (i !== null && (i < 18 || i > 110)) a.push(`Idade calculada fora do esperado (${i} anos)`);
  }
  (p.corequerentes || []).forEach((cr) => {
    const x = cr.pessoa || {};
    if (x.cpf && !cpfValido(x.cpf)) a.push(`CPF de ${x.nome || "outro requerente"} inválido`);
    if (x.cnpj && !cnpjValido(x.cnpj)) a.push(`CNPJ de ${x.nome || "outro requerente"} inválido`);
    if ((cr.tipo === "menor" || cr.tipo === "representado") && !cr.representanteId) a.push(`${x.nome || "Outro requerente"} precisa de representante`);
  });
  (p.ocupantes || []).forEach((o) => { if (o.pessoa?.cpf && !cpfValido(o.pessoa.cpf)) a.push(`CPF de ${o.pessoa.nome || "ocupante"} inválido`); });
  const qtdPessoas = 1 + (p.conjuge?.nome ? 1 : 0) + (p.corequerentes || []).length + (p.ocupantes || []).length;
  if (parseNum(p.social.ocupantes) !== null && parseNum(p.social.ocupantes) < qtdPessoas) a.push(`Pessoas no imóvel (${p.social.ocupantes}) menor que as pessoas cadastradas (${qtdPessoas})`);
  const ri = parseNum(r.renda), rf = parseNum(p.social.rendaFamiliar);
  if (ri !== null && rf !== null && ri > rf) a.push("Renda individual maior que a renda familiar");
  if (ctx.duplicado) a.push(`Possível duplicidade com ${ctx.duplicado.codigo} (mesmo ${ctx.duplicado.motivo})`);
  if (!p.nucleoId) a.push("Morador sem núcleo definido");
  return a;
}
function rotuloCaminho(k, defs) {
  const partes = k.split(".");
  if (partes[0] === "extras") {
    const def = defs.find((d) => d.id === partes[1]);
    if (!def) return "campo personalizado";
    const subId = /^\d+$/.test(partes[2] || "") ? partes[3] : partes[2];
    const sub = subId ? def.subcampos.find((s) => s.id === subId) : null;
    return sub ? `${def.rotulo}: ${sub.rotulo}` : def.rotulo;
  }
  const ult = partes[partes.length - 1];
  return `${ROTULOS[ult] || ult} (${SECAO_NOME[partes[0]] || partes[0]})`;
}

