function seedColaboracao(d, rnd) {
  const pick = (a) => a[Math.floor(rnd() * a.length)];
  const talvez = (x) => rnd() < x;
  const dia = (n, hora = 9, min = 0) => { const x = new Date(Date.now() + n * DIA_MS); x.setHours(hora, min, 0, 0); return x.toISOString(); };
  const data = (n) => dia(n).slice(0, 10);
  const u = (id) => d.usuarios.find((x) => x.id === id);
  const nucleos = d.nucleos.filter((n) => d.processos.some((p) => p.nucleoId === n.id && ativo(p)));
  const rot = (n) => rotuloNucleo(d, n);

  d.setoresMeta = SETORES_META_PADRAO.map((nome) => ({ id: uid("st"), nome, ativo: true }));
  d.ordensServico = nucleos.slice(0, 3).map((n) => {
    const m = municipioDe(d, n.municipioId);
    return { id: uid("os"), nome: `${m ? m.nome : ""} - Alteração no ${n.codigo}`, nucleoReferente: n.codigo, etapaAtual: pick(ETAPAS_PROCESSO), municipio: m ? m.nome : "", estado: m ? m.uf : "SC", observacoes: "Demanda enviada pela prefeitura.", comentarios: [], criadoEm: dia(-14) };
  });
  d.usuarios = d.usuarios.map((u) => ({ ...u, online: ["u2", "u3"].includes(u.id), ultimaAtividade: ["u2", "u3"].includes(u.id) ? new Date().toISOString() : dia(-1, 17) }));
  d.advogados = [{ id: uid("adv"), nome: "Francine Adriana Souza", nacionalidade: "brasileira", estadoCivil: "casada", profissao: "advogada", oab: "45.128", oabUf: "SC", cpf: "02345678901", endereco: "Rua Dr. Getúlio Vargas, 120, sala 3, centro, Ibirama/SC", ativo: true }];
  d.modelosDoc = {};
  d.agendas = clone(AGENDAS_PADRAO);
  d.eventos = [
    { id: uid("ev"), titulo: "Reunião com a prefeitura", descricao: "Apresentar o andamento do protocolo.", inicio: dia(2, 14), fim: dia(2, 15, 30), agendaId: "ag1", entidade: nucleos[0] ? { tipo: "nucleo", id: nucleos[0].id } : null, participantes: ["u1", "u5"], publico: true, cor: "#0F5F5B", status: "ativo", criadoPor: "u1", respostas: { u5: "aceito" } },
    { id: uid("ev"), titulo: "Ida a campo, medições", descricao: "", inicio: dia(1, 8), fim: dia(1, 18), agendaId: "ag2", entidade: nucleos[1] ? { tipo: "nucleo", id: nucleos[1].id } : null, participantes: ["u3"], publico: true, cor: "#9B9C4F", status: "ativo", criadoPor: "u3", respostas: {} },
    { id: uid("ev"), titulo: "Reunião de equipe", descricao: "Revisão das metas da semana.", inicio: dia(-3, 9), fim: dia(-3, 10), agendaId: "ag3", entidade: null, participantes: ["u1", "u2", "u3", "u4", "u5"], publico: true, cor: "#2563B8", status: "ativo", criadoPor: "u1", respostas: { u2: "aceito", u3: "aceito", u4: "recusado" } },
    { id: uid("ev"), titulo: "Assembleia com moradores", descricao: "Apresentação da REURB.", inicio: dia(6, 19), fim: dia(6, 21), agendaId: "ag3", entidade: nucleos[2] ? { tipo: "nucleo", id: nucleos[2].id } : null, participantes: ["u1", "u2"], publico: true, cor: "#12A8C4", status: "ativo", criadoPor: "u2", respostas: {} },
    { id: uid("ev"), titulo: "Período de férias", descricao: "", inicio: dia(12, 0), fim: dia(20, 23), agendaId: "ag3", entidade: null, participantes: ["u4"], publico: true, cor: "#5FD3BF", status: "ativo", criadoPor: "u1", respostas: {} },
  ];

  const municipios = d.municipios.filter((m) => d.remessas.some((r) => r.municipioId === m.id)).slice(0, 3);
  d.planos = municipios.map((m, k) => {
    const remessa = d.remessas.find((r) => r.municipioId === m.id);
    const avanco = [7, 4, 2][k] ?? 3;
    return {
      id: uid("pl"), municipioId: m.id, remessaId: remessa ? remessa.id : null, titulo: `REURB ${m.nome}`,
      descricao: "Plano de trabalho do contrato com a prefeitura.", status: "Em andamento", criadoEm: dia(-120),
      etapas: MODELO_PLANO.map((titulo, i) => ({
        id: uid("et"), titulo, descricao: "", ordem: i,
        status: i < avanco ? "Concluída" : i === avanco ? "Em andamento" : "Pendente",
        prioridade: i === avanco ? pick(["Normal", "Alta"]) : "Normal",
        inicio: data(-110 + i * 14), prazo: data(-110 + i * 14 + 20),
        responsaveis: [pick(["u2", "u3", "u4", "u5"])],
        entregaveis: i <= avanco ? Array.from({ length: 1 + Math.floor(rnd() * 2) }, (_, j) => ({ id: uid("en"), titulo: ["Relatório enviado", "Ata da reunião", "Arquivos entregues", "Conferência do setor"][j % 4], concluido: i < avanco, por: i < avanco ? u("u4").nome : "", em: i < avanco ? dia(-100 + i * 14) : "" })) : [],
        comentarios: i === avanco && talvez(0.7) ? [{ id: uid("cm"), autor: u("u1").nome, texto: "Confirmar a data com a prefeitura antes de fechar esta etapa.", data: dia(-4, 11) }] : [],
      })),
    };
  });

  // Andamentos de cada núcleo, no padrão do kanban de processos do ERP
  const porEtapa = { 0: ["Documental", "Em andamento"], 1: ["Topografia", "Em andamento"], 2: ["Projeto", "Em andamento"], 3: ["Protocolado", "Aguardando Prefeitura"], 4: ["Registro de Imóveis", "Aguardando Cartório"], 5: ["Concluído", "Concluído"] };
  d.nucleos.forEach((n) => {
    const [st, op] = porEtapa[Math.min(n.etapa, 5)] || porEtapa[0];
    n.comercial = talvez(0.75) ? { modalidade: pick(["Entrada e parcelas", "Entrada e parcelas", "Parcelado sem entrada", "Isento (REURB-S)"]), valorTotal: "2400,00", entrada: "400,00", parcelas: "10", valorParcela: "200,00", diaVencimento: "10", primeiroVencimento: data(20), reajuste: "Sem reajuste", observacoes: "", atualizadoEm: dia(-40), por: u("u2").nome } : null;
    n.prioridade = talvez(0.12) ? pick(["Alta", "Urgente"]) : talvez(0.2) ? "Baixa" : "Normal";
    n.etapaProcesso = etapaProcessoPadrao(n);
    n.etapaIniciadaEm = dia(-5 - Math.floor(rnd() * 60));
    n.observacoes = talvez(0.4) ? [{ id: uid("ob"), autor: u("u2").nome, setor: "Comercial", texto: "Falei com a associação de moradores, retornam na semana que vem.", data: dia(-6, 15) }] : [];
    n.historicoEtapas = [];
    n.observacaoInterna = "";
    n.pendencia = talvez(0.25) ? pick(["Aguardando documentos de 3 moradores", "Falta devolutiva da prefeitura", "Conferir confrontações com o cartório"]) : "";
    n.prazoSLA = talvez(0.5) ? data(Math.floor(rnd() * 40) - 10) : "";
    n.andamentos = d.processos.some((p) => p.nucleoId === n.id)
      ? [{ id: uid("an"), status: st, operacional: op, descricaoCliente: "Processo em andamento, seguimos com as etapas previstas.", observacao: n.pendencia || "", previsao: data(20 + Math.floor(rnd() * 40)), data: dia(-2 - Math.floor(rnd() * 20)), por: u(pick(["u2", "u3", "u4", "u5"])).nome }]
      : [];
  });

  const alvo = nucleos[0];
  d.conversas = [
    { id: uid("cv"), tipo: "grupo", titulo: alvo ? rot(alvo) : "Equipe", entidade: alvo ? { tipo: "nucleo", id: alvo.id } : null, participantes: ["u1", "u2", "u3"], criadoPor: "u1",
      mensagens: [
        { id: uid("ms"), autorId: "u1", texto: "Pessoal, como está o levantamento deste núcleo?", data: dia(-2, 9, 12) },
        { id: uid("ms"), autorId: "u3", texto: "Faltam três unidades. Vou amanhã de manhã terminar.", data: dia(-2, 9, 40) },
        { id: uid("ms"), autorId: "u2", texto: "Assim que fechar, eu sigo com a análise documental.", data: dia(-1, 14, 5) },
        { id: uid("ms"), autorId: "u3", texto: "Terminei as três unidades que faltavam. Já dá para seguir.", data: new Date(Date.now() - 900000).toISOString() },
      ], lidaPor: { u1: dia(-1, 15) } },
    { id: uid("cv"), tipo: "grupo", titulo: d.planos[0] ? d.planos[0].titulo : "Plano de trabalho", entidade: d.planos[0] ? { tipo: "plano", id: d.planos[0].id } : null, participantes: ["u1", "u4", "u5"], criadoPor: "u4",
      mensagens: [{ id: uid("ms"), autorId: "u4", texto: "Subi os arquivos da etapa de projeto no plano.", data: dia(-5, 16, 30) }], lidaPor: {} },
    { id: uid("cv"), tipo: "direto", titulo: "", entidade: null, participantes: ["u1", "u5"], criadoPor: "u5",
      mensagens: [
        { id: uid("ms"), autorId: "u5", texto: "A prefeitura pediu correção em dois lotes.", data: dia(-1, 10, 20) },
        { id: uid("ms"), autorId: "u1", texto: "Registre como pendência no processo, por favor.", data: dia(-1, 10, 45) },
      ], lidaPor: { u5: dia(-1, 11) } },
  ];
  return d;
}

/* ---------------- dados de exemplo ---------------- */
function mulberry32(a) {
  return function () { a |= 0; a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
function gerarCPF(rnd) {
  const n = Array.from({ length: 9 }, () => Math.floor(rnd() * 10));
  let s = n.reduce((a, d, i) => a + d * (10 - i), 0); let d1 = (s * 10) % 11; if (d1 === 10) d1 = 0; n.push(d1);
  s = n.reduce((a, d, i) => a + d * (11 - i), 0); let d2 = (s * 10) % 11; if (d2 === 10) d2 = 0; n.push(d2);
  return fmtCPF(n.join(""));
}

